const {chromium}=require('playwright'),assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path');
const hook=`window.demoTest={get state(){return {creative:creativeV78,infinite:devToolsV30.infiniteResources,key:SAVE_KEY,height:feyTallestTowerV75().height,displayed:Number($('height').textContent),animals:wildlifeV71.filter(a=>a.feyV75).map(a=>({x:a.x,y:a.y,species:a.species,task:a.feyV75.task,nails:a.feyV75.nails,stone:a.feyV75.blocks.stone,action:wildlifeAnimationV73(a).state})),store:structuresV46.find(b=>b.type==='storehouse')?.stock,moon:skyStackMoonfire.state,paused:gameClockV76.paused}},run(n){for(let i=0;i<n;i++){Engine.update(eng,1000/60);stepWorkersV55(1000/60);stepStructuresV46(1000/60)}__buttonwood.render(performance.now())},save:saveGame,render(){__buttonwood.render(performance.now())}};`;
(async()=>{const b=await chromium.launch({headless:true,executablePath:'/Applications/Google Chrome.app/Contents/MacOS/Google Chrome'}),p=await b.newPage({viewport:{width:1280,height:900}}),errors=[];p.on('pageerror',e=>errors.push(e.message));p.on('console',m=>{if(m.type()==='error')console.log('BROWSER',m.text())});await p.addInitScript(()=>{requestAnimationFrame=()=>0;localStorage.setItem('skyStack.save.v1','normal-world-sentinel')});await p.route('**/game-v82-moonfire-demo.txt*',async r=>{const a=await r.fetch();await r.fulfill({response:a,body:await a.text()+'\n'+hook})});const url=new URL(process.env.SKY_TEST_URL||'http://127.0.0.1:8766/tower-of-babel/');url.searchParams.set('demo','moonfire');await p.goto(url.href);await p.waitForFunction(()=>window.demoTest&&window.__buttonwood,null,{polling:100});let s=await p.evaluate(()=>demoTest.state);assert(s.paused);assert(!s.creative&&!s.infinite);assert.equal(s.key,'tower.moonfire.survival-demo.v2');assert(s.height>=100);assert.equal(s.displayed,s.height);assert.equal(s.animals.length,7);assert(s.animals.every(a=>a.task==='Tower'&&a.nails===100&&a.stone===50));await p.locator('#pauseResumeV76').click();const start=s.animals.reduce((n,a)=>n+a.stone,0);await p.evaluate(()=>demoTest.run(500));s=await p.evaluate(()=>demoTest.state);assert(s.animals.reduce((n,a)=>n+a.stone,0)<start,'animals actually build with finite stone');assert(s.animals.filter(a=>['wood-mouse','mole'].includes(a.species)).some(a=>a.stone<50),'ground critters build too');assert(s.moon.active);assert.equal(await p.evaluate(()=>localStorage.getItem('skyStack.save.v1')),'normal-world-sentinel');await p.evaluate(()=>demoTest.render());const qa=path.join(__dirname,'../buttonwood/qa/moonfire-demo');fs.mkdirSync(qa,{recursive:true});await p.screenshot({path:path.join(qa,'builders.png')});await p.evaluate(()=>demoTest.save());await p.reload();await p.waitForFunction(()=>window.demoTest&&window.__buttonwood,null,{polling:100});assert((await p.evaluate(()=>demoTest.state)).paused);assert.equal((await p.evaluate(()=>demoTest.state)).displayed,(await p.evaluate(()=>demoTest.state)).height);assert((await p.evaluate(()=>demoTest.state)).moon.active);assert(! (await p.evaluate(()=>demoTest.state)).creative);assert.deepEqual(errors,[]);console.log('PASS isolated survival demo, pause-to-start, seven actual Fey builders, finite supplies, guaranteed normal event roll, reload continuity and preserved normal save');await b.close()})().catch(e=>{console.error(e);process.exit(1)});
